{* Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/faq-cards.json
    The questions of FaqSplit as cards: the topic, the question, the answer and a read-more link; with an icon square on top in the icons shape. Shapes: grid3, grid4, icons (three columns).
    Props (p): items, labels, cards. *}
{var $v_items = ($p['items'] ?? null)}
{var $v_labels = ($p['labels'] ?? null)}
{var $v_cards = ($p['cards'] ?? 'grid3')}
{capture $c_9}
  {foreach ui_l($v_items) as $v_q}
    {capture $c_8}
      {if ui_t(ui_eq($v_cards, 'icons'))}
        {capture $c_1}
          {=ui_include('ui/lucide-icon/lucide-icon.latte', ['p' => ['Name' => ui_s(ui_get($v_q, ['icon'])), 'Size' => 20]])|noescape}
        {/capture}
        {=ui_include('ui/box/box.latte', ['p' => ['Class' => 'flex size-10 shrink-0 items-center justify-center rounded bg-muted'], 'children' => $c_1])|noescape}
      {/if}
      {capture $c_5}
        {capture $c_2}
          {=ui_text(ui_get($v_q, ['category']))}
        {/capture}
        {=ui_include('ui/badge/badge.latte', ['p' => ['Variant' => 'secondary', 'Size' => 'sm', 'Class' => 'w-fit'], 'children' => $c_2])|noescape}
        {capture $c_3}
          {=ui_text(ui_get($v_q, ['question']))}
        {/capture}
        {=ui_include('ui/title/title.latte', ['p' => ['As' => ui_i(3), 'Size' => 'base', 'Weight' => 'semibold'], 'children' => $c_3])|noescape}
        {capture $c_4}
          {=ui_text(ui_get($v_q, ['answer']))}
        {/capture}
        {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Class' => 'text-muted-foreground'], 'children' => $c_4])|noescape}
      {/capture}
      {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '2'], 'children' => $c_5])|noescape}
      {capture $c_7}
        {capture $c_6}
          {=ui_text(ui_get($v_labels, ['more']))}
          {=ui_include('ui/lucide-icon/lucide-icon.latte', ['p' => ['Name' => 'arrow-right', 'Size' => 16]])|noescape}
        {/capture}
        {=ui_include('ui/link/link.latte', ['p' => ['Href' => '#/faq', 'Variant' => 'default', 'Size' => 'sm', 'Class' => 'font-medium'], 'children' => $c_6])|noescape}
      {/capture}
      {=ui_include('ui/box/box.latte', ['p' => ['Class' => 'mt-auto'], 'children' => $c_7])|noescape}
    {/capture}
    {=ui_include('blocks/article-block.latte', ['p' => ['className' => ui_cnv(['rounded bg-card inset-ring inset-ring-border flex flex-col gap-4 p-6']), 'testid' => 'faq-card'], 'children' => $c_8])|noescape}
  {/foreach}
{/capture}
{=ui_include('ui/box/box.latte', ['p' => ['Class' => ui_s((ui_t(ui_eq($v_cards, 'grid4')) ? 'grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4' : 'grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3')), 'Attrs' => ui_attrs(['data-testid', 'faq'])], 'children' => $c_9])|noescape}
